/* ==================== Generic RU FAQ template — RU port of genericFaqFor() in
   js/faq-templates.js. Reads NON_GENUINE_BRANDS from js/data.js (same set for both
   languages). Used for the 76 SKUs without a PRODUCT_DEEP_RU entry. ==================== */
function genericFaqFor_ru(p, categoryNameRu) {
  const cat = categoryNameRu || (typeof CATEGORIES_RU !== 'undefined' ? (CATEGORIES_RU[p.cat] || p.cat) : p.cat);

  const availQA = (() => {
    if (p.status === 'quote') {
      return {
        q: 'Есть ли сейчас ' + p.model + ' в наличии и каков срок поставки?',
        a: 'Текущий остаток, состояние и срок поставки на этой странице не подтверждены. Отправьте точный код заказа и нужное количество на info@fouwell.com, чтобы проверить эти условия для вашего запроса.'
      };
    }
    if (p.status === 'legacy') {
      return {
        q: 'Есть ли ' + p.model + ' в наличии и сколько занимает доставка?',
        a: p.model + ' — устаревшая линейка: уже не выпускается серийно, но Fouwell может поставить его из собственных складских остатков и сети поставщиков. Срок поставки обычно больше, чем для товара в наличии; сообщите нужное количество, и мы подтвердим текущую доступность и срок поставки в течение одного рабочего дня.'
      };
    }
    if (p.status === 'discont') {
      // p.no_known_replacement / p.condition_note_ru (2026-09-16): see js/faq-templates.js
      // genericFaqFor() header comment — RU mirror of the same fix, own translation rather than
      // reusing p.condition_note (that field is English-only, for the EN template).
      if (p.no_known_replacement) {
        const conditionNoteRu = p.condition_note_ru ? ' ' + p.condition_note_ru : '';
        return {
          q: p.model + ' отмечен как снятый с производства — он ещё доступен, и есть ли замена?',
          a: p.model + ' снят с производства ' + p.brand + ', и мы пока не определили официальную замену для этого номера детали.' + conditionNoteRu + ' Мы можем поискать оставшиеся складские остатки через нашу сеть поставщиков — отправьте детали применения на info@fouwell.com, и мы подтвердим, что доступно, и по возможности предложим текущий аналог.'
        };
      }
      return {
        q: p.model + ' отмечен как заменённый — он ещё доступен, и чем он заменён?',
        a: p.model + ' снят с производства ' + p.brand + ' и заменён текущим аналогом. Мы можем помочь найти оставшиеся складские остатки ' + p.model + ', где они ещё доступны, либо порекомендовать прямую замену — отправьте детали применения на info@fouwell.com, и мы подтвердим лучший вариант.'
      };
    }
    return {
      q: 'Есть ли ' + p.model + ' в наличии и как быстро он отгружается?',
      a: 'Да, этот товар есть в наличии — товары в наличии отгружаются в течение 24 часов через DHL, FedEx или UPS, авиадоставка обычно занимает 3–5 рабочих дней в большинство стран Азии, Ближнего Востока и Европы; для крупных заказов доступна морская доставка.'
    };
  })();

  const nonGenuine = typeof NON_GENUINE_BRANDS !== 'undefined' && NON_GENUINE_BRANDS.has(p.brand);
  // p.condition_note_ru (2026-09-16): RU mirror of js/faq-templates.js's p.condition_note —
  // see that file's header comment for why a genuinely-branded but refurbished/used unit
  // shouldn't be described as sourced through official channels with original packaging.
  const refurbished = !!p.condition_note_ru;

  const authenticityUnconfirmed = !!p.authenticity_note_ru;
  const genuineQA = authenticityUnconfirmed
    ? {
        q: 'Подтверждены ли подлинность и происхождение конкретной партии ' + p.brand + ' ' + p.model + '?',
        a: 'На этой странице указаны каталожный номер производителя и характеристики по каталогу. Источник поставки и состояние предлагаемой партии здесь не подтверждены. До заказа свяжитесь с нами, чтобы уточнить сведения о партии и доступные подтверждающие документы.'
      }
    : nonGenuine
    ? {
        q: 'Является ли ' + p.brand + ' ' + p.model + ' оригинальным, и откуда Fouwell его поставляет?',
        a: p.model + ' продаётся под именем ' + p.brand + ' как заявленная совместимая деталь, не являющаяся оригинальной продукцией производителя — мы открыто сообщаем об этом, а не создаём иного впечатления. Каждая единица функционально протестирована и проверена перед отгрузкой. Если вам нужна именно оригинальная деталь бренда, сообщите нам, и мы предложим её отдельным вариантом.'
      }
    : refurbished
    ? {
        q: 'Является ли ' + p.brand + ' ' + p.model + ' оригинальным, и откуда Fouwell его поставляет?',
        a: 'Да, это оригинальная деталь ' + p.brand + '. ' + p.condition_note_ru + ' Каждая единица функционально протестирована и проверена перед отгрузкой, и мы сразу сообщаем о её состоянии, а не выдаём за новую.'
      }
    : {
        q: 'Является ли ' + p.brand + ' ' + p.model + ' оригинальным, и откуда Fouwell его поставляет?',
        a: 'Да. Fouwell поставляет каждую деталь ' + p.brand + ' по официальным каналам бренда или через проверенных авторизованных дистрибьюторов, и каждая единица проходит 100% проверку перед отгрузкой. Для ' + p.model + ' мы можем по запросу предоставить оригинальную упаковку, маркировку и, при наличии, заводской протокол испытаний.'
      };

  const shippingQA = {
    q: 'Как отправляется ' + p.model + ' и осуществляете ли вы международную доставку?',
    a: p.status === 'quote'
      ? 'Способ доставки, страхование, упаковка и срок зависят от подтверждённого заказа. Укажите страну назначения и количество, чтобы уточнить доступные условия.'
      : 'Мы отправляем по всему миру через DHL, FedEx, UPS (авиа) или морем для крупных заказов, с полной страховкой' +
      (nonGenuine || refurbished ? '' : ' и оригинальной упаковкой производителя') +
      '. Мы также используем склад в Гонконге для более быстрой региональной консолидации некоторых заказов.'
  };

  return [
    genuineQA,
    availQA,
    {
      q: 'Существует ли минимальный объём заказа (MOQ) для ' + p.model + '?',
      a: p.status === 'quote'
        ? 'Минимальное количество заказа и цена зависят от подтверждённого предложения. Укажите нужное количество, чтобы мы могли проверить условия.'
        : 'Фиксированного MOQ для стандартных деталей нет — мы регулярно отправляем как единичные позиции для обслуживания и запчастей, так и крупные партии для производственных линий. Большие объёмы дают более выгодную цену за единицу; сообщите нужное количество для расчёта цены.'
    },
    {
      q: 'Предоставляете ли вы гарантию на этот товар (' + cat + ')?',
      a: p.status === 'quote'
        ? 'Применимые гарантийные условия для предлагаемой партии необходимо подтвердить в коммерческом предложении до заказа.'
        : 'Да. Каждая деталь, поставляемая Fouwell, имеет гарантию замены сроком 12 месяцев на производственные дефекты. Гарантия не распространяется на повреждения из-за неправильного монтажа, неверной проводки или напряжения, либо использования вне официальных спецификаций производителя.'
    },
    {
      q: 'Можете ли вы помочь подобрать аналог для более старого или другого номера детали ' + p.brand + '?',
      a: p.status === 'quote'
        ? 'Отправьте полный номер детали и сведения о применении на info@fouwell.com. Мы проверим информацию и сообщим, можно ли определить совместимый аналог для вашего применения.'
        : 'Да. Отправьте точный номер детали (старый или новый) на info@fouwell.com — наши инженеры подтвердят текущий аналог, наличие и цену — как правило, в течение одного рабочего дня, часто в течение часа в рабочее время Азия/Шанхай.'
    },
    shippingQA
  ];
}

